/**
 * Task #943 — probe: the role-gated Me tabs (Performance / Delegates /
 * Assist) must agree between the top-bar menu (LensSectionTabs, which
 * filters via meSectionVisibleForRole) and the COMMITTED screen catalog
 * (generated by scripts/generate-screen-catalog.ts from the same shared
 * definition). For every role, a Me-lens tab shows in the menu iff the
 * catalog entry lists that role.
 *
 * Run: pnpm --filter @workspace/atelier run test:me-lens-gating
 */
import assert from "node:assert/strict";
import { SCREEN_CATALOG } from "../../../../lib/screen-catalog/src/catalog";
import { LENSES, visibleMeSectionsForRole, visibleLensesForRole } from "./lens";

// Mirror of the generator's INTERNAL_ROLES (personaRoles minus
// alliance_partner, whose world is only the partner portal + chat).
const INTERNAL_ROLES = [
  "founding_partner",
  "partner",
  "finance",
  "hr",
  "senior_manager",
  "consultant",
  "contractor",
  "partner_firm_resource",
  "board_observer",
  "recruiter",
  "compliance_officer",
  "employee",
] as const;

const meLens = LENSES.find((l) => l.id === "me")!;
const meCatalog = new Map(
  SCREEN_CATALOG.filter((e) => e.id.startsWith("me.")).map((e) => [e.id, e]),
);

// Every Me-lens section must exist in the catalog.
for (const s of meLens.sections) {
  assert.ok(meCatalog.has(`me.${s.id}`), `catalog missing entry me.${s.id}`);
}

let checks = 0;
for (const role of INTERNAL_ROLES) {
  // The catalog only lists roles that can see the Me lens at all.
  const seesMeLens = visibleLensesForRole(role).some((l) => l.id === "me");
  const menuIds = new Set(
    seesMeLens ? visibleMeSectionsForRole(role).map((s) => s.id) : [],
  );
  for (const s of meLens.sections) {
    const entry = meCatalog.get(`me.${s.id}`)!;
    const inCatalog = entry.roles.includes(role);
    const inMenu = menuIds.has(s.id);
    assert.equal(
      inCatalog,
      inMenu,
      `me.${s.id} for role "${role}": menu=${inMenu} but catalog=${inCatalog} — ` +
        `the shared gating (lens.ts meSectionVisibleForRole) and the committed ` +
        `catalog disagree. Regenerate: pnpm --filter @workspace/atelier run generate:screen-catalog`,
    );
    checks++;
  }
}

console.log(
  `me-lens gating probe ✓ — menu and screen catalog agree (${checks} role×tab checks)`,
);
